<?php require __DIR__.'/../../app/bootstrap.php';require_admin($pdo);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$role=$_POST['role']??'user';if(in_array($role,['user','admin'],true)){$pdo->prepare('UPDATE users SET role=? WHERE id=?')->execute([$role,$id]);flash('success','User role updated.');}header('Location:/admin/users.php');exit;}$rows=$pdo->query('SELECT u.*,COALESCE(w.balance,0) balance FROM users u LEFT JOIN wallets w ON w.user_id=u.id ORDER BY u.id DESC LIMIT 200')->fetchAll();require __DIR__.'/../../app/layout.php';header_html('Users');?><div class="card"><h2>Users</h2><div class="table-wrap"><table><tr><th>Name</th><th>Email</th><th>Phone</th><th>Balance</th><th>Role</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['phone'])?></td><td><?=money($r['balance'])?></td><td><?=e($r['role'])?></td><td><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="role"><option <?=$r['role']==='user'?'selected':''?>>user</option><option <?=$r['role']==='admin'?'selected':''?>>admin</option></select><button class="btn small">Save</button></form></td></tr><?php endforeach;?></table></div></div><?php footer_html();
